#!/usr/bin/env python3
"""
Homicide worldwide (culprits), 17 October 2026. Not a numbered round: needs no
other patch and changes nothing other rounds touch.

One row under Destruction > Of individuals > Of humans: the owner's homicide
map (maps repo, homicide.html), read each day like the other site maps.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTE = "## Homicide worldwide (17 October, a separate chat)\n\nNot a numbered round: it changes nothing other rounds touch, so it applies\nbefore or after them, and this note goes at the end of this file. Its map\nfile goes into the maps repo by hand. No tiles patch. No app.js?v= bump.\n\n- New map in WelcomeToYourGalaxy/maps: homicide.html (Leaflet; every mark a\n  circleMarker, polygon or polyline with its popup bound when made, each part\n  a layerGroup named in L.control.layers, so extract.mjs reads it the usual\n  way; no \"rich\" builder). The Destruction page's section (1) Of individuals,\n  8 parts: homicide by country (every row of UNODC's\n  data_cts_intentional_homicide.xlsx, released 12 July 2026, for 208\n  countries, territories and parts, shaded by the latest rate, every figure in\n  the box; Iraq's two parts each also carry Iraq's whole-country rows, so 207\n  shapes); cult-related homicides named in the OJP/California occult crime\n  primer (4); Wikipedia's list of criminal enterprises, gangs and syndicates\n  placed by Wikidata or the list's own place headings (1,140 placed, ringed\n  where only a country is known; 176 with no place listed in the map's About\n  box); gang territories from the three readable gangsigns.org Google My Maps\n  (LA 2026, Southern California, South Bend; no licence stated); stand-your-\n  ground law by US state and territory and nine other jurisdictions\n  (Wikipedia); the page's animal sacrifice sites (207) and animal fighting\n  venues and regions (144). Extract on the file: 5,770 features, 8 overlays.\n- registry.json: homicide_worldwide (url = maps/main/homicide.html), so the\n  tiles refresh's sitemaps job builds sitemaps/homicide_worldwide.places.geojson\n  and .boxes.json each full run. The row draws nothing until the first\n  refresh after the map is in the maps repo.\n- app.js: the row in SITE_MAPS (route sitemap, keepColour), SHORT_NAMES,\n  LAYER_KIND (human, downstream), LAYER_SITE, NOT_LIVE; PANEL_ORDER: first\n  under Destruction > Of individuals > Of humans, before the bundles. The\n  map's overlays are the row's facet.\n- test.mjs: one block, \"homicide worldwide (17 October)\", just before the\n  final pass/fail line; round 102b's Of groups check now allows this row\n  (and comments) straight after Of individuals > Of humans.\n"

DIFF = ""

FILES = ["map/app.js", "map/test.mjs", "pipeline/sitemaps/registry.json"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("homicide: run from the culprits repository root")
    h = root / "HANDOFF.md"
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("homicide: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", *FILES, check=False)
            sys.exit("homicide: the diff did not apply:\n" + r.stdout + r.stderr)
        print("homicide: applied")
    text = h.read_text(encoding="utf-8")
    if NOTE.split("\n", 1)[0] not in text:
        h.write_text(text.rstrip("\n") + "\n\n\n" + NOTE, encoding="utf-8")


if __name__ == "__main__":
    main()
